// Every in-flight row's routed target is read with one request per table
// ("Fetch targets", over the stored Supabase credential). "Scan + flip" used
// to make one request per row with the service-role key written into its
// source (moved 2026-10-03).
const LOOKUPS = {
  tasks: 'id,status,updated_at',
  leads: 'id,deep_enriched_at,promoted_task_id',
  visibility_targets: 'id,status,deep_enriched_at',
  guests: 'id,status,pitch_draft',
  content_ideas: 'id,state',
  bets: 'id,status,est_mrr_impact_usd',
};
const fetched = $input.first().json.body;
const inflight = Array.isArray(fetched) ? fetched : [];
// Always all six, so "Scan + flip" runs even when nothing is in flight. An
// empty list asks for no rows.
return Object.entries(LOOKUPS).map(([table, cols]) => {
  const ids = [...new Set(inflight.filter(r => r.target_table === table && r.target_id).map(r => r.target_id))];
  return { json: { table, url: `https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/${table}?id=in.(${ids.join(',')})&select=${cols}` } };
});

// Phase 2: for every in_flight inbox row, check if the routed row has
// reached a state where Krish needs to look at it. If yes, flip the
// inbox row to needs_krish (the decisions_waiting view surfaces it).
// The reads run before this node and the writes after it, over the stored
// Supabase credential (moved out of this node's source on 2026-10-03, with
// the service-role key). The rules are unchanged.
const fetched = $('Fetch in-flight rows').first().json.body;
const inflight = Array.isArray(fetched) ? fetched : [];

// One lookup per table. A failed read leaves its table out, which is what
// the old per-row catch did: no flip, and the time-out still applies.
const plans = $('Plan lookups').all();
const targets = {};
$input.all().forEach((res, i) => {
  const k = res.pairedItem && typeof res.pairedItem.item === 'number' ? res.pairedItem.item : i;
  const table = plans[k] && plans[k].json.table;
  const r = res.json;
  if (!table || !r || r.statusCode < 200 || r.statusCode >= 300 || !Array.isArray(r.body)) return;
  targets[table] = new Map(r.body.map(t => [t.id, t]));
});

const patches = [];
for (const r of inflight) {
  const target_table = r.target_table;
  const target_id    = r.target_id;
  if (!target_table || !target_id) continue;
  const refIso = r.updated_at;
  let needs = false;
  if (targets[target_table]) {
    const t = targets[target_table].get(target_id);
    if (!t) continue;
    if (target_table === 'tasks') {
      needs = ['waiting','pending-agatha-review','pending-review','blocked'].includes(t.status) && t.updated_at && t.updated_at > refIso;
    } else if (target_table === 'leads') {
      needs = !!t.deep_enriched_at && !t.promoted_task_id;
    } else if (target_table === 'visibility_targets') {
      needs = t.status === 'enriched' || !!t.deep_enriched_at;
    } else if (target_table === 'guests') {
      needs = t.status === 'enriched' || !!t.pitch_draft;
    } else if (target_table === 'content_ideas') {
      needs = ['review','seeded'].includes(t.state);
    } else if (target_table === 'bets') {
      needs = t.status === 'live' && t.est_mrr_impact_usd == null;
    }
  }

  // Time-out branch: 7 days in_flight without movement → mark failed.
  const ageMs = Date.now() - new Date(r.updated_at).getTime();
  if (!needs && ageMs > 7 * 86400000) {
    patches.push({ json: { id: r.id, body: {
      status: 'failed', archive_reason: 'classifier_failed', archived_at: new Date().toISOString(),
    } } });
    continue;
  }
  if (needs) {
    patches.push({ json: { id: r.id, body: { status: 'needs_krish' } } });
  }
}

// "Write inbox status" sends one PATCH per change. With none, the run ends here.
return patches;
